Below is a self‑contained C++ program that demonstrates several common ways to use lambda expressions.  
Feel free to copy‑paste it into a file (e.g. `lambda_demo.cpp`) and compile with `g++ -std=c++17 lambda_demo.cpp`.

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>   // std::accumulate

int main()
{
    /* 1. A simple lambda that takes no arguments and returns nothing. */
    auto say_hello = []() {
        std::cout << "Hello, world!\n";
    };
    say_hello();

    /* 2. Lambda that captures a local variable by value. */
    int factor = 3;
    auto multiply_by_factor = [factor](int x) { return x * factor; };
    std::cout << "5 * factor = " << multiply_by_factor(5) << '\n';

    /* 3. Lambda that captures by reference so that the lambda can modify the outer variable. */
    int count = 0;
    auto increment = [&count]() { ++count; };  // captures count by reference
    increment(); increment(); increment();
    std::cout << "count after 3 increments = " << count << '\n';

    /* 4. Mutable lambda that can change a captured-by-value copy. */
    int captured = 10;
    auto mutable_inc = [captured]() mutable { return ++captured; };
    std::cout << "mutable lambda first call: " << mutable_inc() << '\n';
    std::cout << "mutable lambda second call: " << mutable_inc() << '\n';
    std::cout << "original captured unchanged: " << captured << '\n';

    /* 5. Generic lambda (C++14) – works with any type. */
    auto print_type = [](auto x) {
        std::cout << "Value: " << x << " (type: " << typeid(x).name() << ")\n";
    };
    print_type(42);
    print_type(3.14);
    print_type(std::string("hello"));

    /* 6. Using a lambda as a custom comparator in std::sort. */
    std::vector<int> numbers{5, 3, 8, 1, 9};
    std::sort(numbers.begin(), numbers.end(),
              [](int a, int b) { return a > b; });  // descending order
    std::cout << "Sorted descending: ";
    for (int n : numbers) std::cout << n << ' ';
    std::cout << '\n';

    /* 7. Lambda with std::for_each to apply an operation to every element. */
    std::cout << "Numbers after multiplying by 2: ";
    std::for_each(numbers.begin(), numbers.end(),
                  [](int& n) { n *= 2; });
    for (int n : numbers) std::cout << n << ' ';
    std::cout << '\n';

    /* 8. Lambda used as a callback in a function. */
    auto apply_callback = [](int x, const std::function<void(int)>& cb) {
        int result = x * x;
        cb(result);
    };

    apply_callback(4, [](int res) {
        std::cout << "Callback: 4 squared is " << res << '\n';
    });

    /* 9. Lambda as a std::transform operation (map). */
    std::vector<int> original{1, 2, 3, 4, 5};
    std::vector<int> squares(original.size());
    std::transform(original.begin(), original.end(), squares.begin(),
                   [](int x) { return x * x; });
    std::cout << "Squares: ";
    for (int s : squares) std::cout << s << ' ';
    std::cout << '\n';

    /* 10. Lambda used in std::accumulate to compute a sum. */
    int sum = std::accumulate(original.begin(), original.end(), 0,
                              [](int acc, int val) { return acc + val; });
    std::cout << "Sum of original vector: " << sum << '\n';

    return 0;
}
```

